Properties.Octopus.Action.Script.ScriptBody:
$ErrorActionPreference = "Stop"

function Get-Parameter($Name, $Default, [switch]$Required) {
    $result = $null
    if ($OctopusParameters -ne $null) {
        $result = $OctopusParameters[$Name]
    }
    if ([string]::IsNullOrWhiteSpace($result)) {
        if ($Required) {
            throw "Required parameter $Name not specified"
        }

        $result = $Default
    }
    return $result
}

function ConvertTo-DotNetVersion([string]$VersionText) {
    # Splits "10.0.0-rc.1.25451.107" into the numeric part (as [version]) and the pre-release label.
    # Returns $null when the text is not a version, so stray folders are ignored.
    $parts = $VersionText.Trim().Split("-", 2)
    $number = $parts[0]
    if ($number -notmatch "\.") {
        $number = "$number.0"
    }
    $parsed = $null
    if (-not [version]::TryParse($number, [ref]$parsed)) {
        return $null
    }
    $preRelease = if ($parts.Length -gt 1) { $parts[1] } else { "" }
    return [pscustomobject]@{ Text = $VersionText.Trim(); Number = $parsed; PreRelease = $preRelease }
}

function Compare-DotNetVersion($Left, $Right) {
    # Returns -1, 0 or 1. Numeric parts are compared as versions (so 10.0 > 6.0), and a pre-release
    # is lower than the release with the same number, following the SemVer 2.0 precedence rules.
    $result = $Left.Number.CompareTo($Right.Number)
    if ($result -ne 0) {
        return [Math]::Sign($result)
    }
    if (-not $Left.PreRelease -and -not $Right.PreRelease) {
        return 0
    }
    if (-not $Left.PreRelease) {
        return 1
    }
    if (-not $Right.PreRelease) {
        return -1
    }
    $leftIds = $Left.PreRelease.Split(".")
    $rightIds = $Right.PreRelease.Split(".")
    for ($i = 0; $i -lt [Math]::Max($leftIds.Length, $rightIds.Length); $i++) {
        if ($i -ge $leftIds.Length) {
            return -1
        }
        if ($i -ge $rightIds.Length) {
            return 1
        }
        $leftIsNumber = $leftIds[$i] -match "^\d+$"
        $rightIsNumber = $rightIds[$i] -match "^\d+$"
        if ($leftIsNumber -and $rightIsNumber) {
            $result = ([long]$leftIds[$i]).CompareTo([long]$rightIds[$i])
        } elseif ($leftIsNumber) {
            $result = -1
        } elseif ($rightIsNumber) {
            $result = 1
        } else {
            $result = [string]::Compare($leftIds[$i], $rightIds[$i], [StringComparison]::OrdinalIgnoreCase)
        }
        if ($result -ne 0) {
            return [Math]::Sign($result)
        }
    }
    return 0
}

function Get-InstalledRuntimeVersions($SharedFrameworkName) {
    # Each installed runtime is a folder under <dotnet>\shared\<framework>\<version>, which is also what "dotnet --list-runtimes" reports.
    # ProgramW6432 points at the 64-bit Program Files even when the script runs in a 32-bit PowerShell host.
    $programFiles = if ($env:ProgramW6432) { $env:ProgramW6432 } else { $env:ProgramFiles }
    $sharedFrameworkPath = Join-Path $programFiles "dotnet\shared\$SharedFrameworkName"
    if (-not (Test-Path $sharedFrameworkPath)) {
        return @()
    }
    return @(Get-ChildItem $sharedFrameworkPath -Directory | ForEach-Object { ConvertTo-DotNetVersion $_.Name } | Where-Object { $_ -ne $null })
}

function Assert-RuntimeInstalled($RuntimeName, $SharedFrameworkName, $TargetVersion, [bool]$Exact) {
    $installedVersions = Get-InstalledRuntimeVersions $SharedFrameworkName | Sort-Object { $_.Number }, { -not $_.PreRelease }, { $_.PreRelease }
    $matchedVersions = @($installedVersions | Where-Object {
        $comparison = Compare-DotNetVersion $_ $TargetVersion
        if ($Exact) { $comparison -eq 0 } else { $comparison -ge 0 }
    })
    if ($matchedVersions.Count -eq 0) {
        $installedText = if ($installedVersions) { ($installedVersions | ForEach-Object { $_.Text }) -join ", " } else { "none" }
        $requirement = if ($Exact) { "exactly $($TargetVersion.Text)" } else { "$($TargetVersion.Text) or greater" }
        throw "Can't find $RuntimeName $requirement installed in the machine. Installed versions: $installedText."
    }
    $matchedVersions | ForEach-Object { Write-Host "Found $RuntimeName $($_.Text) installed in the machine." }
}

$targetVersionText = (Get-Parameter "TargetVersion" -Required).Trim()
$exact = [boolean]::Parse((Get-Parameter "Exact" -Required))
$checkAspNetCore = [boolean]::Parse((Get-Parameter "CheckASPdotNETCore" -Required))
$targetVersion = ConvertTo-DotNetVersion $targetVersionText
if ($targetVersion -eq $null) {
    throw "TargetVersion '$targetVersionText' is not a valid .NET version. Use a version such as 8.0, 8.0.11 or 10.0.0-rc.1."
}

Assert-RuntimeInstalled ".NET Core Runtime" "Microsoft.NETCore.App" $targetVersion $exact
if ($checkAspNetCore) {
    Assert-RuntimeInstalled "ASP.NET Core Runtime" "Microsoft.AspNetCore.App" $targetVersion $exact
}
